from __future__ import annotations

import csv
import gzip
import hashlib
import json
import sys
from pathlib import Path

import numpy as np


TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
FIXTURE_DIR = TASK_DIR / "fixtures"
PROTOCOL_FILE = FIXTURE_DIR / "reference_space_protocol.json"
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(report: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def import_map_fingerprint():
    sys.path.insert(0, str(SOURCE_DIR))
    try:
        from skfp.fingerprints import MAPFingerprint
    finally:
        if sys.path and sys.path[0] == str(SOURCE_DIR):
            sys.path.pop(0)
    return MAPFingerprint


def load_protocol() -> dict[str, object]:
    protocol = json.loads(PROTOCOL_FILE.read_text(encoding="utf-8"))
    config = protocol["encoding"]
    panels = protocol["panels"]
    if int(config["fp_size"]) <= 0 or int(config["radius"]) < 0:
        raise ValueError("invalid protocol dimensions")
    if not panels["reference_rows"] or not panels["query_rows"]:
        raise ValueError("empty benchmark panel")
    return protocol


def load_benchmark_rows(protocol: dict[str, object]) -> dict[int, dict[str, str]]:
    provenance = protocol["raw_benchmark_input"]
    dataset_path = FIXTURE_DIR / provenance["local_file"]
    if dataset_path.suffix != ".gz" or not dataset_path.is_file():
        raise FileNotFoundError("benchmark input is unavailable")

    expected_hash = str(provenance["sha256"]).lower()
    actual_hash = hashlib.sha256(dataset_path.read_bytes()).hexdigest()
    if actual_hash != expected_hash:
        raise ValueError("benchmark input checksum mismatch")

    with gzip.open(dataset_path, "rt", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        if reader.fieldnames is None:
            raise ValueError("benchmark input has no header")
        reader.fieldnames = [
            field.removeprefix("# ").strip() for field in reader.fieldnames
        ]
        rows: dict[int, dict[str, str]] = {}
        for row_number, row in enumerate(reader, start=1):
            rows[row_number] = {
                "id": str(row["ID"]),
                "title": str(row["Mol_Title"]),
                "smiles": str(row["SMILES"]),
            }
    return rows


def panel_from_rows(
    rows: dict[int, dict[str, str]], row_numbers: list[int]
) -> list[dict[str, str]]:
    panel = []
    for row_number in row_numbers:
        if row_number not in rows:
            raise IndexError("benchmark row is unavailable")
        item = dict(rows[row_number])
        item["source_row"] = str(row_number)
        panel.append(item)
    return panel


def dense(array: object) -> np.ndarray:
    if hasattr(array, "toarray"):
        return np.asarray(array.toarray())
    return np.asarray(array)


def array_summary(array: object) -> dict[str, object]:
    values = dense(array)
    nonfinite_count = int(np.count_nonzero(~np.isfinite(values)))
    return {
        "shape": list(values.shape),
        "dtype": str(values.dtype),
        "nonfinite_count": nonfinite_count,
        "nonzero_count": int(np.count_nonzero(values)),
        "minimum": int(values.min()) if values.size else None,
        "maximum": int(values.max()) if values.size else None,
        "unique_value_count": int(np.unique(values).size) if values.size else 0,
    }


def coordinate_agreement(left: np.ndarray, right: np.ndarray) -> float:
    if left.shape != right.shape or left.size == 0:
        return 0.0
    return float(np.mean(left == right))


def make_transformer(MAPFingerprint, config: dict[str, object]):
    return MAPFingerprint(
        fp_size=int(config["fp_size"]),
        radius=int(config["radius"]),
        include_duplicated_shingles=bool(config["include_duplicated_shingles"]),
        include_chirality=bool(config["include_chirality"]),
        variant=str(config["variant"]),
        random_state=int(config["random_state"]),
        sparse=bool(config["sparse"]),
    )


def retrieval_observation(
    reference: list[dict[str, str]],
    queries: list[dict[str, str]],
    reference_vectors: np.ndarray,
    query_vectors: np.ndarray,
    top_k: int,
) -> dict[str, object]:
    rankings: list[dict[str, object]] = []
    scores: list[float] = []
    for query, query_vector in zip(queries, query_vectors):
        agreements = np.asarray(
            [coordinate_agreement(query_vector, row) for row in reference_vectors],
            dtype=float,
        )
        order = np.argsort(-agreements, kind="stable")[:top_k]
        ranked = [
            {
                "reference_id": reference[index]["id"],
                "coordinate_agreement": float(agreements[index]),
            }
            for index in order
        ]
        scores.extend(float(value) for value in agreements)
        rankings.append({"query_id": query["id"], "neighbors": ranked})

    return {
        "rankings": rankings,
        "agreement_distribution": {
            "minimum": float(np.min(scores)) if scores else None,
            "median": float(np.median(scores)) if scores else None,
            "maximum": float(np.max(scores)) if scores else None,
        },
    }


def repeat_observation(
    reference_vectors: np.ndarray,
    query_vectors: np.ndarray,
    repeated_reference: np.ndarray,
    repeated_queries: np.ndarray,
    reference: list[dict[str, str]],
    queries: list[dict[str, str]],
    top_k: int,
) -> dict[str, object]:
    first = retrieval_observation(
        reference, queries, reference_vectors, query_vectors, top_k
    )
    repeated = retrieval_observation(
        reference, queries, repeated_reference, repeated_queries, top_k
    )
    rank_delta_counts = []
    for first_row, repeated_row in zip(first["rankings"], repeated["rankings"]):
        first_ids = [item["reference_id"] for item in first_row["neighbors"]]
        repeated_ids = [item["reference_id"] for item in repeated_row["neighbors"]]
        rank_delta_counts.append(
            sum(left != right for left, right in zip(first_ids, repeated_ids))
        )
    return {
        "coordinate_delta_counts": [
            int(np.count_nonzero(left != right))
            for left, right in zip(reference_vectors, repeated_reference)
        ],
        "query_coordinate_delta_counts": [
            int(np.count_nonzero(left != right))
            for left, right in zip(query_vectors, repeated_queries)
        ],
        "top_rank_delta_counts": rank_delta_counts,
    }


def main() -> int:
    try:
        protocol = load_protocol()
        rows = load_benchmark_rows(protocol)
        panels = protocol["panels"]
        reference = panel_from_rows(rows, panels["reference_rows"])
        queries = panel_from_rows(rows, panels["query_rows"])
        MAPFingerprint = import_map_fingerprint()
        config = protocol["encoding"]
        top_k = int(protocol["observation"]["top_k"])
        transformer = make_transformer(MAPFingerprint, config)
        reference_vectors = dense(
            transformer.transform([item["smiles"] for item in reference])
        )
        query_vectors = dense(transformer.transform([item["smiles"] for item in queries]))
        combined_vectors = dense(
            transformer.transform(
                [item["smiles"] for item in reference + queries]
            )
        )
        repeated_reference = dense(
            make_transformer(MAPFingerprint, config).transform(
                [item["smiles"] for item in reference]
            )
        )
        repeated_queries = dense(
            make_transformer(MAPFingerprint, config).transform(
                [item["smiles"] for item in queries]
            )
        )
    except TypeError:
        return write_report(
            {
                "schema_version": "1.2",
                "status": "pre_fix_expected_failure",
                "observation": {
                    "reference_rows": len(protocol["panels"]["reference_rows"])
                    if "protocol" in locals()
                    else None,
                    "query_rows": len(protocol["panels"]["query_rows"])
                    if "protocol" in locals()
                    else None,
                    "stage": "representation_transform",
                },
            },
            1,
        )
    except Exception as exc:  # noqa: BLE001 - infrastructure has its own state.
        return write_report(
            {
                "schema_version": "1.2",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
            },
            2,
        )

    summaries = {
        "reference": array_summary(reference_vectors),
        "queries": array_summary(query_vectors),
        "combined": array_summary(combined_vectors),
    }
    workflow_completed = all(
        summary["shape"][0] > 0
        and len(summary["shape"]) == 2
        and summary["nonfinite_count"] == 0
        for summary in summaries.values()
    )

    observation = {
        "input": {
            "reference_ids": [item["id"] for item in reference],
            "query_ids": [item["id"] for item in queries],
            "source_rows": [item["source_row"] for item in reference + queries],
        },
        "protocol": {
            "method_commit": protocol["method_contract"]["scikit_fingerprints_commit"],
            "representation": str(config["variant"]),
            "width": int(config["fp_size"]),
            "radius": int(config["radius"]),
        },
        "panel_summaries": summaries,
        "retrieval": retrieval_observation(
            reference, queries, reference_vectors, query_vectors, top_k
        ),
        "repeat_observation": repeat_observation(
            reference_vectors,
            query_vectors,
            repeated_reference,
            repeated_queries,
            reference,
            queries,
            top_k,
        ),
    }
    return write_report(
        {
            "schema_version": "1.2",
            "status": "workflow_completed" if workflow_completed else "runner_failure",
            "observation": observation,
        },
        0 if workflow_completed else 1,
    )


if __name__ == "__main__":
    raise SystemExit(main())
# Public reproduction workbench

Run from this directory with the task runtime:

```text
python reproduce.py
```

The workbench reads `fixtures/reference_space_protocol.json` and the raw
compressed benchmark input beside it. The input is an unmodified compound list
from the pinned MAP4 repository. The fixture records its source URL, commit,
path, license context, and checksum, together with a small reference/query row
selection for an offline methods observation.

The workbench applies the versioned method contract to the reference and query
rows, then emits a finite JSON report containing:

- source IDs and row provenance for the two panels;
- shape, dtype, non-finite count, nonzero count, and value-range summaries for
  the reference, query, and combined panels;
- ranked reference neighbors for each query with their coordinate-agreement
  scores and an aggregate agreement distribution; and
- coordinate-delta counts and top-rank delta counts from an independent repeat
  of the same protocol.

These are ordinary method-validation observations from a retrieval workflow.
They are not a task-authored reference vector, an expected ranking, or a
semantic verdict. The report does not encode a pass/fail answer for any
individual representation or scientific interpretation.

The report is written to
`outputs/public_reproduction_report.json` and printed to stdout. Its status
meanings are:

- `workflow_completed`: the configured input was transformed and the report
  contains non-empty finite panel observations;
- `pre_fix_expected_failure`: the public API call reached the representation
  transform stage but the pinned workflow could not be completed on the
  pre-fix snapshot; and
- `runner_failure`: an import, dependency, malformed-input, checksum, or other
  execution failure prevented a scientific observation.

The workbench does not inspect signatures or source text and does not publish a
private oracle or a task-authored expected output.
